// ---- OBJ Export Utilities ----

/**
 * Convert a BufferGeometry to OBJ format string.
 * Geometry should already be in the desired coordinate space.
 */
function bufferGeometryToOBJ(geometry, objectName = 'mesh') {
    if (!geometry.getAttribute('normal')) {
        geometry.computeVertexNormals();
    }

    const pos = geometry.getAttribute('position');
    const norm = geometry.getAttribute('normal');
    const idx = geometry.getIndex();

    let lines = [];
    lines.push(`# OBJ file`);
    lines.push(`o ${objectName}`);

    // Vertices
    for (let i = 0; i < pos.count; i++) {
        lines.push(`v ${pos.getX(i).toFixed(6)} ${pos.getY(i).toFixed(6)} ${pos.getZ(i).toFixed(6)}`);
    }

    // Normals
    for (let i = 0; i < norm.count; i++) {
        lines.push(`vn ${norm.getX(i).toFixed(6)} ${norm.getY(i).toFixed(6)} ${norm.getZ(i).toFixed(6)}`);
    }

    // Faces
    if (idx) {
        for (let i = 0; i < idx.count; i += 3) {
            const a = idx.getX(i) + 1;
            const b = idx.getX(i + 1) + 1;
            const c = idx.getX(i + 2) + 1;
            lines.push(`f ${a}//${a} ${b}//${b} ${c}//${c}`);
        }
    } else {
        for (let i = 0; i < pos.count; i += 3) {
            lines.push(`f ${i + 1}//${i + 1} ${i + 2}//${i + 2} ${i + 3}//${i + 3}`);
        }
    }

    return lines.join('\n') + '\n';
}

/**
 * Export a single mesh to OBJ, applying its world matrix to the geometry.
 */
function meshToOBJ(mesh) {
    mesh.updateMatrixWorld(true);
    const geom = mesh.geometry.clone();
    geom.applyMatrix4(mesh.matrixWorld);
    if (!geom.getAttribute('normal')) {
        geom.computeVertexNormals();
    }
    return bufferGeometryToOBJ(geom, mesh.name || 'mesh');
}

